package alphametics

import (
	"fmt"
	"math"
	"sort"
	"strings"
)

// Solve solves an alphametics puzzle of the form "WORD + WORD == WORD".
// It returns a mapping from each letter (as a one-character string) to its
// digit, or an error if the puzzle has no solution.
func Solve(puzzle string) (map[string]int, error) {
	sides := strings.Split(puzzle, "==")
	if len(sides) != 2 {
		return nil, fmt.Errorf("invalid puzzle: %q", puzzle)
	}

	// coeff[r] is the total place value of letter r across the addends
	// (positive) and the result (negative). A valid solution makes the
	// weighted sum exactly zero.
	coeff := map[rune]int64{}
	leading := map[rune]bool{}
	add := func(word string, sign int64) error {
		if len(word) == 0 {
			return fmt.Errorf("invalid puzzle: %q", puzzle)
		}
		if len(word) > 1 {
			leading[word[0]] = true
		}
		for i, r := range word {
			if r < 'A' || r > 'Z' {
				return fmt.Errorf("invalid puzzle: %q", puzzle)
			}
			place := int64(1)
			for j := i + 1; j < len(word); j++ {
				place *= 10
			}
			coeff[r] += sign * place
		}
		return nil
	}

	for _, w := range strings.FieldsFunc(sides[0], func(r rune) bool { return r == '+' }) {
		if err := add(w, 1); err != nil {
			return nil, err
		}
	}
	if err := add(sides[1], -1); err != nil {
		return nil, err
	}

	// Try the most significant letters first so the sum is pruned early.
	letters := make([]rune, 0, len(coeff))
	for r := range coeff {
		letters = append(letters, r)
	}
	sort.Slice(letters, func(i, j int) bool {
		return abs64(coeff[letters[i]]) > abs64(coeff[letters[j]])
	})

	// bound[i] is the largest magnitude the unassigned letters from index i
	// onward can still contribute, so a partial sum outside [-bound, bound]
	// can never reach zero.
	bound := make([]int64, len(letters)+1)
	for i := len(letters) - 1; i >= 0; i-- {
		bound[i] = bound[i+1] + 9*abs64(coeff[letters[i]])
	}

	assigned := map[rune]int{}
	digitUsed := make([]bool, 10)
	var solve func(i int, sum int64) bool
	solve = func(i int, sum int64) bool {
		if i == len(letters) {
			return sum == 0
		}
		r := letters[i]
		start := 0
		if leading[r] {
			start = 1
		}
		for d := start; d <= 9; d++ {
			if digitUsed[d] {
				continue
			}
			newSum := sum + int64(d)*coeff[r]
			if newSum > bound[i] || newSum < -bound[i] {
				continue
			}
			assigned[r] = d
			digitUsed[d] = true
			if solve(i+1, newSum) {
				return true
			}
			digitUsed[d] = false
			delete(assigned, r)
		}
		return false
	}

	if !solve(0, 0) {
		return nil, fmt.Errorf("no solution found for puzzle %q", puzzle)
	}

	out := make(map[string]int, len(assigned))
	for r, d := range assigned {
		out[string(r)] = d
	}
	return out, nil
}

func abs64(v int64) int64 {
	if v < 0 {
		return -v
	}
	return v
}

